insert into dnew values
(1, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'On a pulmonary artery catheter, which reading confirms pulmonary arterial hypertension rather than left heart disease?', '["Mean PAP 18 mmHg with a wedge pressure of 8 mmHg", "Mean PAP 40 mmHg with a wedge pressure of 28 mmHg", "Mean PAP 12 mmHg with a high cardiac output and wedge 6", "Mean PAP 40 mmHg with a wedge pressure of 10 mmHg"]'::jsonb, 3, 'Pre-capillary PH has a raised mean PAP (over 20–25 mmHg) with a normal wedge (15 mmHg or less). A high wedge points to left heart disease.', 'Cardiovascular'),
(2, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'The ECG of a patient with long-standing pulmonary hypertension commonly shows:', '["Left axis deviation with tall R waves in V5–V6", "ST elevation in V1–V4 with deep Q waves", "A short PR interval with delta waves", "Right axis deviation, P pulmonale and RV strain"]'::jsonb, 3, 'RV hypertrophy causes right axis deviation, dominant R in V1 and peaked P waves in lead II.', 'Cardiovascular'),
(3, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Which drug should be avoided in severe pulmonary hypertension because it can precipitate RV collapse at induction?', '["A low-dose dobutamine infusion started beforehand", "A large propofol bolus causing sudden systemic hypotension", "Small titrated doses of noradrenaline before induction", "Inhaled nitric oxide given through the ventilator"]'::jsonb, 1, 'Systemic hypotension reduces RV coronary perfusion; the RV then fails. Vasopressors are prepared before induction.', 'Cardiovascular'),
(4, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'For an ICU patient with acute RV failure from pulmonary embolism, the nurse anticipates:', '["Noradrenaline for coronary perfusion; avoid large fluid boluses", "IV furosemide as the first-line treatment of RV failure", "High PEEP with large tidal volumes to recruit the lungs", "A rapid 2-litre fluid bolus to increase the RV preload"]'::jsonb, 0, 'Excess fluid dilates the RV and worsens septal shift. Thrombolysis is considered in massive PE.', 'Cardiovascular'),
(5, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'A haemopneumothorax should be managed with:', '["Needle aspiration only, repeated daily until the chest is dry", "A small pigtail catheter for air only, kept clamped between checks", "Observation with high-flow oxygen therapy and a repeat X-ray", "A large-bore drain in the safe triangle on an underwater seal"]'::jsonb, 3, 'Blood requires a larger drain; the drain must not be clamped.', 'Cardiovascular'),
(6, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'The ''safe triangle'' for chest drain insertion is bounded by:', '["Pectoralis major, latissimus dorsi and the 5th intercostal space", "Scapula, vertebral column and the 12th rib at the back", "Sternum, clavicle and the 2nd rib at the front of the chest", "Umbilicus, iliac crest and the costal margin below"]'::jsonb, 0, 'It avoids the internal mammary artery, the long thoracic nerve and abdominal organs.', 'Cardiovascular'),
(7, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Among renal transplant types, the best expected outcome is generally seen with:', '["Cadaveric donation", "Living-related donation", "Living non-related donation", "All types have identical outcomes"]'::jsonb, 1, 'A closer genetic match, as seen with living-related donors, is associated with the best transplant outcomes.', 'Cardiovascular'),
(8, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'The standard triple immunosuppression regimen after renal transplant includes:', '["Aspirin + clopidogrel + warfarin to prevent graft vessel thrombosis", "Prednisolone alone in high dose for the first year after surgery", "Tacrolimus or ciclosporin + mycophenolate or azathioprine + prednisolone", "Insulin + metformin + glipizide to control the post-transplant glucose"]'::jsonb, 2, 'This three-drug combination targets the immune response through different mechanisms to prevent rejection.', 'Cardiovascular'),
(9, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Which of the following is an absolute contraindication to renal transplant?', '["Well-controlled hypertension", "Mild anaemia", "Active uncontrolled infection", "Age over 60 with good health"]'::jsonb, 2, 'An active, uncontrolled infection makes the immunosuppression required after transplant dangerously unsafe.', 'Cardiovascular'),
(10, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'In the first 24 hours after renal transplant, urine output of 600 mL/hour should be:', '["Restricted by stopping all IV fluids", "Replaced hour-by-hour with IV fluid", "Treated with IV furosemide to promote diuresis", "Ignored, as it will settle by itself"]'::jsonb, 1, 'The new graft may cause a large diuresis (post-transplant polyuria); replacement fluids are calculated each hour.', 'Cardiovascular'),
(11, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'A transplant recipient on immunosuppression develops a fever of 38.4 °C. The nurse should:', '["Stop all immunosuppressant drugs without waiting for orders", "Give paracetamol and review again at the next day''s ward round", "Treat as possible infection or rejection and inform the team at once", "Assume it is a normal post-operative fever and observe only"]'::jsonb, 2, 'Immunosuppressed patients may present atypically; cultures and early treatment are needed.', 'Cardiovascular'),
(12, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Therapeutic plasma exchange, or plasmapheresis, works by:', '["Removing plasma containing harmful antibodies and replacing it", "Adding concentrated red blood cells to the circulation", "Diffusing small solutes only, exactly like haemodialysis", "Removing only white blood cells from the circulation"]'::jsonb, 0, 'Plasmapheresis separates and removes plasma containing pathogenic autoantibodies, immune complexes, or toxins, replacing it with fresh frozen plasma or albumin solution, and is used in conditions like Guillain-Barre syndrome, myasthenia gravis, and TTP.', 'Cardiovascular'),
(13, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Before therapeutic plasma exchange, the nurse checks that the patient has:', '["A full stomach to prevent hypoglycaemia during the exchange", "Had all IV access removed to reduce the risk of infection", "Good vascular access, and baseline calcium, clotting and vital signs", "Had their usual antihypertensive doses doubled that morning"]'::jsonb, 2, 'Plasma exchange removes clotting factors and can cause hypocalcaemia and hypotension.', 'Cardiovascular'),
(14, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Plasma exchange is a recognised treatment for:', '["Uncomplicated essential hypertension", "Simple urinary tract infection with fever", "Iron-deficiency anaemia in pregnancy", "Myasthenic crisis and Guillain-Barré syndrome"]'::jsonb, 3, 'It removes pathogenic antibodies. Other indications include TTP and some vasculitides.', 'Cardiovascular'),
(15, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Highly protein-bound drugs given just before plasma exchange are likely to:', '["Be removed with the plasma, reducing their effect", "Become more potent after the exchange is complete", "Have no change at all in their plasma levels", "Cause toxicity from accumulation in the tissues"]'::jsonb, 0, 'Doses of drugs such as some antibiotics may need to be given after the exchange.', 'Cardiovascular'),
(16, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Following nephrectomy, an ICU patient must be monitored especially for:', '["Raised intracranial pressure and seizures", "Hypothyroidism with bradycardia and cold skin", "Hyperglycaemia and diabetic ketoacidosis", "Bleeding, remaining kidney function and pneumothorax"]'::jsonb, 3, 'The flank approach can injure the pleura; urine output reflects the remaining kidney.', 'Cardiovascular'),
(17, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'Emphysema on a chest X-ray typically shows:', '["Hyperinflation, flat diaphragms and increased lucency", "Small lungs with raised diaphragms on both sides", "Bilateral fluffy alveolar shadowing with large heart", "A single dense lobar consolidation with air bronchogram"]'::jsonb, 0, 'Patients may have bullae, which can rupture into a pneumothorax during positive pressure ventilation.', 'Cardiovascular'),
(18, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'A patient with status asthmaticus on the ventilator has rising airway pressures and falling BP. The nurse suspects:', '["Fluid overload from the IV aminophylline infusion", "A normal response to the nebulised bronchodilators", "Auto-PEEP from air trapping; briefly disconnect to allow exhalation", "The endotracheal tube has slipped into the right main bronchus"]'::jsonb, 2, 'Air trapping raises intrathoracic pressure and reduces venous return. A low rate and long expiratory time help.', 'Cardiovascular'),
(19, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'A ventilated COPD patient''s ABG shows pH 7.50, PaCO₂ 30 mmHg (4 kPa), HCO₃⁻ 34 mmol/L. This indicates:', '["Diabetic ketoacidosis needing an insulin infusion", "Over-ventilation with chronic metabolic compensation", "Acute respiratory acidosis needing a higher rate", "A normal blood gas for a patient with severe COPD"]'::jsonb, 1, 'The kidneys retained bicarbonate during chronic CO₂ retention; ventilating to a ''normal'' CO₂ causes alkalosis.', 'Cardiovascular'),
(20, 'Cardio-respiratory and Renal Gaps: Pulmonary Hypertension, Transplant, Apheresis', 'BiPAP for acute hypercapnic COPD exacerbation works mainly by:', '["IPAP boosts tidal volume to clear CO₂; EPAP splints the airways", "EPAP alone delivers a high, fixed oxygen fraction to the patient", "It removes the need for any arterial blood gas monitoring", "It sedates the patient so that the breathing rate falls"]'::jsonb, 0, 'Failure (worsening pH after 1–2 hours) indicates the need for intubation.', 'Cardiovascular'),
(21, 'Trauma: Primary Survey, Procedures and Polytrauma', 'In the ABCDE primary survey, ''D'' stands for:', '["Drugs: give analgesia before assessing pain", "Diagnosis: reach a definitive diagnosis first", "Disability: GCS or AVPU, pupils and glucose", "Documentation: write the complete history"]'::jsonb, 2, '''E'' is exposure with prevention of hypothermia.', 'Shock & Haemorrhage'),
(22, 'Trauma: Primary Survey, Procedures and Polytrauma', 'The nurse notes a ''seatbelt sign'' across the abdomen of a crash victim. This should raise suspicion of:', '["Cerebral contusion from a whiplash movement", "Hollow viscus and lumbar (Chance) spine injuries", "Isolated skin bruising without deeper injury", "Pulmonary embolism from the lower limb veins"]'::jsonb, 1, 'Bowel injury can be missed by FAST; serial examination and CT are needed.', 'Shock & Haemorrhage'),
(23, 'Trauma: Primary Survey, Procedures and Polytrauma', 'The main limitation of FAST compared with DPL or CT is that FAST:', '["It cannot detect any free fluid in the abdomen", "It requires the patient to be moved to the CT room", "It can miss hollow viscus and retroperitoneal injuries", "It uses ionising radiation like plain X-rays"]'::jsonb, 2, 'FAST detects free fluid but not its source or bowel perforation.', 'Shock & Haemorrhage'),
(24, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Before inserting a central venous catheter, the nurse should prepare:', '["Only a syringe, a cannula and a dressing", "A urinary catheter set with sterile water", "A clean dressing pack and non-sterile gloves only", "Full aseptic set, ultrasound, flushes, and a head-down position"]'::jsonb, 3, 'The CLABSI insertion bundle includes hand hygiene, maximal barrier precautions, chlorhexidine and ultrasound guidance.', 'Shock & Haemorrhage'),
(25, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Immediately after a jugular central line insertion, the patient becomes breathless with reduced breath sounds on that side. The nurse suspects:', '["Air embolism of the coronary arteries", "Arterial puncture with haematoma only", "Pneumothorax", "Allergic reaction to chlorhexidine"]'::jsonb, 2, 'A chest X-ray is urgent; tension pneumothorax needs immediate decompression.', 'Shock & Haemorrhage'),
(26, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Signs of venous air embolism during central line removal include:', '["Bradycardia with high blood pressure and a clear chest", "Fever with rigors starting 24 hours after removal", "Local bruising and swelling at the insertion site only", "Sudden breathlessness, hypotension and a ''mill-wheel'' murmur"]'::jsonb, 3, 'Place the patient left side down and head-down, give 100% oxygen and call for help.', 'Shock & Haemorrhage'),
(27, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Pericardiocentesis in tamponade is usually performed via the:', '["Right second intercostal space", "Left fifth intercostal space in the mid-axillary line", "Suprasternal notch", "Subxiphoid approach, aiming toward the left shoulder"]'::jsonb, 3, 'Ultrasound guidance reduces complications such as ventricular puncture.', 'Shock & Haemorrhage'),
(28, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Removal of only 30–50 mL of blood during pericardiocentesis in tamponade typically produces:', '["No change because more is needed", "Worsening of hypotension", "Marked improvement in blood pressure", "Immediate cardiac arrest"]'::jsonb, 2, 'The pericardial pressure-volume curve is steep, so small volumes matter.', 'Shock & Haemorrhage'),
(29, 'Trauma: Primary Survey, Procedures and Polytrauma', 'An underwater seal chest drain stops swinging and the patient is comfortable with normal breath sounds. This most likely means:', '["The patient has tension pneumothorax", "The lung has fully re-expanded", "There is a large air leak", "The drain is in the abdomen"]'::jsonb, 1, 'Lack of swing may also mean blockage; assess the patient and chest X-ray.', 'Shock & Haemorrhage'),
(30, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Chest drain bubbling that is continuous during both inspiration and expiration in a ventilated patient suggests:', '["Normal function of the drain in a ventilated patient", "Complete re-expansion of the lung on that side", "A large air leak from the lung (bronchopleural fistula) or system", "Blockage of the drain by a large blood clot"]'::jsonb, 2, 'Check connections first; if persistent, it may be a bronchopleural fistula.', 'Shock & Haemorrhage'),
(31, 'Trauma: Primary Survey, Procedures and Polytrauma', 'In a polytrauma patient with a head injury and hypotension, the target systolic BP is usually:', '["At least 100–110 mmHg to protect cerebral perfusion", "Above 180 mmHg to force blood into the brain", "Any value, as BP does not affect head injury", "70–80 mmHg, as permissive hypotension in trauma"]'::jsonb, 0, 'Hypotension doubles mortality in traumatic brain injury, so permissive hypotension is avoided.', 'Shock & Haemorrhage'),
(32, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Massive transfusion in trauma is generally defined as:', '["One unit every 24 hours for a period of one week", "One blood volume in 24 hours (about 10 units of red cells)", "Any transfusion given in the emergency department", "Two units of red cells transfused within 24 hours"]'::jsonb, 1, 'Massive transfusion protocols use a fixed ratio of red cells, plasma and platelets.', 'Shock & Haemorrhage'),
(33, 'Trauma: Primary Survey, Procedures and Polytrauma', 'A complication of massive transfusion the ICU nurse should anticipate is:', '["Alkalosis from the bicarbonate in stored blood", "Low calcium, high potassium, hypothermia, coagulopathy", "High calcium and low glucose with a fever", "Polycythaemia and hypertension with oedema"]'::jsonb, 1, 'Warm all products and check ionised calcium regularly.', 'Shock & Haemorrhage'),
(34, 'Trauma: Primary Survey, Procedures and Polytrauma', 'A trauma patient arrives with an unstable pelvic fracture and hypotension. The immediate step is:', '["Elevate both legs on pillows to raise the BP", "Log-roll repeatedly to examine the back fully", "Apply a pelvic binder at the greater trochanters", "Insert a urethral catheter before anything else"]'::jsonb, 2, 'The binder closes the pelvic ring and reduces venous bleeding.', 'Shock & Haemorrhage'),
(35, 'Trauma: Primary Survey, Procedures and Polytrauma', 'The secondary survey in trauma is performed:', '["Before any assessment of the airway or breathing", "Only after the patient is discharged from hospital", "After the primary survey and resuscitation are under way", "Instead of the primary survey if the patient is stable"]'::jsonb, 2, 'It is a head-to-toe examination with history (AMPLE).', 'Shock & Haemorrhage'),
(36, 'Trauma: Primary Survey, Procedures and Polytrauma', 'The AMPLE history in trauma stands for:', '["Alcohol, Mental state, Pupils, Limbs and the ECG", "Age, Mechanism, Pain, Location and Effects of injury", "Allergies, Medications, Past history, Last meal, Events", "Airway, Mouth, Pulse, Lungs and Eyes of the patient"]'::jsonb, 2, 'The last meal time matters for aspiration risk during anaesthesia.', 'Shock & Haemorrhage'),
(37, 'Trauma: Primary Survey, Procedures and Polytrauma', 'A urinary catheter should not be inserted in a trauma patient with:', '["Blood at the meatus, perineal bruising or high-riding prostate", "A full bladder after an uncomplicated pelvic operation", "A stable femoral shaft fracture held in traction", "A head injury with a GCS of 13 and confusion"]'::jsonb, 0, 'These suggest urethral injury; a urologist may insert a suprapubic catheter.', 'Shock & Haemorrhage'),
(38, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Damage control surgery in polytrauma means:', '["Complete repair of every injury in one long single operation", "A short operation to control bleeding and contamination; repair later", "Delaying any surgery until the patient''s temperature is normal", "Only conservative treatment, with surgery avoided altogether"]'::jsonb, 1, 'The patient is resuscitated in ICU before returning for definitive surgery.', 'Shock & Haemorrhage'),
(39, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Signs of a developing tension pneumothorax in a ventilated patient include:', '["Hypertension and bradycardia only", "Rising airway pressures, falling SpO₂, hypotension", "Falling airway pressures with a rising SpO₂", "An increased tidal volume with no other change"]'::jsonb, 1, 'Needle decompression is followed by a chest drain.', 'Shock & Haemorrhage'),
(40, 'Trauma: Primary Survey, Procedures and Polytrauma', 'Fluid resuscitation in a severe burns patient arriving at 4 hours post-burn requires that:', '["No fluid at all until the burns have been cleaned and dressed", "Half of the volume over the next 8 hours from the arrival time", "The full 24-hour volume calculated from the time of arrival", "The first half of the Parkland volume over the remaining 4 hours"]'::jsonb, 3, 'Timing is calculated from the time of injury, so fluid already missed must be caught up.', 'Shock & Haemorrhage'),
(41, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'According to the Monro-Kellie doctrine, approximately what proportion of intracranial volume is occupied by brain tissue?', '["~80%", "~50%", "~30%", "~10%"]'::jsonb, 0, 'Brain tissue makes up roughly 80% of intracranial volume, with blood and CSF each contributing approximately 10%.', 'Neurology'),
(42, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'A PbtO2 value below which threshold on Licox monitoring is generally considered critical and warrants urgent intervention?', '["Above 40 mmHg", "Above 100 mmHg", "Below 15-20 mmHg", "Below 60 mmHg"]'::jsonb, 2, 'A PbtO2 below approximately 15-20 mmHg indicates cerebral tissue ischemia and requires prompt interventions such as optimizing oxygenation, CPP, and hemodynamics.', 'Neurology'),
(43, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'A patient''s ICP is 28 mmHg and MAP is 80 mmHg. The cerebral perfusion pressure is:', '["52 mmHg, below the target of 60–70 mmHg", "108 mmHg, above the target range", "80 mmHg, within the target range", "28 mmHg, normal after head injury"]'::jsonb, 0, 'CPP = MAP − ICP. Raise MAP or lower ICP to restore CPP.', 'Neurology'),
(44, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'A ''plateau wave'' (Lundberg A wave) on ICP monitoring indicates:', '["Improving brain compliance after treatment", "Sustained ICP of 50–100 mmHg; compliance exhausted", "A blocked transducer giving falsely low readings", "Normal pulsatile ICP changes with the heartbeat"]'::jsonb, 1, 'A waves are ominous and require urgent intervention.', 'Neurology'),
(45, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'A dampened, flat ICP waveform on an EVD system most likely means:', '["Infection of the CSF with raised white cells", "Excellent brain oxygenation and low ICP", "Normal ICP with good intracranial compliance", "Blockage or air in the system, or a collapsed ventricle"]'::jsonb, 3, 'Check for clamps, kinks and air; do not flush toward the patient without medical order.', 'Neurology'),
(46, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'CSF from an EVD becomes cloudy, the patient febrile, and CSF glucose low. The nurse suspects:', '["Ventriculitis", "Subarachnoid haemorrhage", "Normal post-insertion change", "Over-drainage of CSF"]'::jsonb, 0, 'Send CSF for culture; strict asepsis when sampling reduces infection.', 'Neurology'),
(47, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'The ICP threshold that generally triggers treatment in severe traumatic brain injury is above:', '["10–15 mmHg", "5–10 mmHg", "40–45 mmHg", "20–22 mmHg"]'::jsonb, 3, 'Normal ICP is about 5–15 mmHg.', 'Neurology'),
(48, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'Hyperosmolar therapy for raised ICP uses:', '["Mannitol or hypertonic saline", "Hartmann''s solution boluses", "5% dextrose boluses", "Albumin 4.5% only"]'::jsonb, 0, 'Hypotonic fluids worsen cerebral oedema and must be avoided.', 'Neurology'),
(49, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'Short-term hyperventilation to PaCO₂ 4–4.5 kPa (30–35 mmHg) lowers ICP by:', '["Increased cerebral blood flow and oxygen delivery", "Dilatation of the cerebral veins and sinuses", "Cerebral vasoconstriction, reducing blood volume", "Increased CSF production by the choroid plexus"]'::jsonb, 2, 'Prolonged or excessive hyperventilation risks cerebral ischaemia.', 'Neurology'),
(50, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'A combination of hypertension, bradycardia and irregular breathing in a head-injured patient is:', '["Beck''s triad of cardiac tamponade", "Cushing''s triad, a late sign of herniation", "Virchow''s triad of venous thrombosis", "Charcot''s triad of ascending cholangitis"]'::jsonb, 1, 'It needs immediate escalation and treatment of ICP.', 'Neurology'),
(51, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'In targeted temperature management, the most common recommended target after cardiac arrest is:', '["Room temperature with no monitoring needed", "38–39 °C to help fight any infection", "28–30 °C maintained for at least 72 hours", "A constant 32–36 °C, avoiding fever afterwards"]'::jsonb, 3, 'Fever prevention for at least 72 hours is also emphasised.', 'Neurology'),
(52, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'A myasthenic crisis is distinguished from a cholinergic crisis by:', '["Strength improves after edrophonium (or neostigmine)", "Pinpoint pupils and bradycardia are present", "Strength worsens after edrophonium is given", "Excess salivation and diarrhoea are present"]'::jsonb, 0, 'Cholinergic crisis from excess anticholinesterase causes SLUDGE features and worsens with more drug.', 'Neurology'),
(53, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'In myasthenic crisis, the ICU nurse should avoid giving:', '["Pyridostigmine at the prescribed times as ordered", "IV immunoglobulin over five days by infusion", "Aminoglycosides and magnesium, which worsen weakness", "Oxygen therapy by face mask at 4 L/min"]'::jsonb, 2, 'Many drugs, including some antibiotics and beta-blockers, aggravate myasthenia.', 'Neurology'),
(54, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'A patient with tetanus in ICU should be nursed in:', '["A quiet, dark room with minimal stimulation", "A brightly lit open ward", "A room with constant visitors", "A busy area near the nurses'' station noise"]'::jsonb, 0, 'Stimuli trigger painful spasms; sedation, magnesium and airway protection are needed.', 'Neurology'),
(55, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'Autonomic dysfunction in severe tetanus presents with:', '["Polyuria and severe hypokalaemia", "Hypoglycaemia and drowsiness", "Labile BP, tachycardia, sweating and arrhythmias", "Persistent hypothermia and bradycardia"]'::jsonb, 2, 'Magnesium sulphate infusion helps control spasms and autonomic instability.', 'Neurology'),
(56, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'ICU-Acquired Weakness differs from Guillain-Barré Syndrome in that ICU-AW involves:', '["Segmental demyelination of the nerves", "Axonal degeneration without demyelination", "Only facial and bulbar muscle weakness", "No nerve involvement at all, only muscle"]'::jsonb, 1, 'GBS damages the myelin sheath, while ICU-AW damages the axon directly without demyelination.', 'Neurology'),
(57, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'Which muscle group is almost always SPARED in ICU-Acquired Weakness?', '["Facial and ocular muscles", "Hip girdle muscles", "Respiratory muscles", "Proximal limb muscles"]'::jsonb, 0, 'Unlike the proximal limb and respiratory muscles, the face and eyes are almost never involved in ICU-AW.', 'Neurology'),
(58, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'Toxic epidermal necrolysis involves skin detachment of more than:', '["1% of body surface area", "5% of body surface area", "10% of body surface area", "30% of body surface area"]'::jsonb, 3, 'Stevens-Johnson syndrome is under 10%; overlap is 10–30%.', 'Neurology'),
(59, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'The most common trigger of toxic epidermal necrolysis is:', '["Exposure to cold, damp weather for several days", "A viral upper respiratory infection, with no drug", "Food allergy to peanuts, shellfish or eggs", "Drugs, e.g. sulphonamides, anticonvulsants, nevirapine"]'::jsonb, 3, 'Nevirapine and cotrimoxazole are common causes in Nigeria.', 'Neurology'),
(60, 'Neuro-critical Care: ICP, Licox, EVD, Neuromuscular Disorders', 'Eye care in toxic epidermal necrolysis is vital because:', '["It treats the underlying drug reaction directly", "The eyes are never involved in this condition", "Conjunctival involvement can cause scarring and blindness", "It only prevents dry skin around the eyelids"]'::jsonb, 2, 'Ophthalmology review, lubricants and lysis of adhesions are needed.', 'Neurology'),
(61, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Intra-abdominal hypertension grade III corresponds to an IAP of:', '["12–15 mmHg", "Over 25 mmHg", "16–20 mmHg", "21–25 mmHg"]'::jsonb, 3, 'Grade I is 12–15, grade II 16–20, grade III 21–25 and grade IV over 25 mmHg.', 'GI, Endocrine & Metabolic'),
(62, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'A primary cause of abdominal compartment syndrome is:', '["Septic shock from pneumonia", "Abdominal trauma with intra-abdominal bleeding", "Massive fluid resuscitation for burns", "Large-volume ascites from cirrhosis only"]'::jsonb, 1, 'Secondary ACS comes from conditions outside the abdomen, e.g. large fluid resuscitation in burns or sepsis.', 'GI, Endocrine & Metabolic'),
(63, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Non-surgical measures to reduce intra-abdominal pressure include:', '["Large-volume IV fluid boluses to improve gut perfusion", "A tight abdominal binder to support the abdominal wall", "Prone positioning without any support under the abdomen", "NG decompression, sedation, avoiding a positive fluid balance"]'::jsonb, 3, 'Neuromuscular blockade may be used briefly; drainage of ascites helps.', 'GI, Endocrine & Metabolic'),
(64, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Bleeding from a stress ulcer in a ventilated patient is suggested by:', '["Fresh blood suctioned from the endotracheal tube", "Coffee-ground NG aspirate and a falling haemoglobin", "Bright red blood in the urinary catheter bag", "Bruising around the umbilicus and flanks"]'::jsonb, 1, 'Melaena and haemodynamic instability may follow; urgent endoscopy may be needed.', 'GI, Endocrine & Metabolic'),
(65, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'A patient with severe acute pancreatitis develops oliguria, hypoxia and hypotension on day 2. This represents:', '["Simple dehydration that needs oral fluids", "A systemic inflammatory response with organ failure", "Gallstones passing into the duodenum", "Normal recovery from an attack of pancreatitis"]'::jsonb, 1, 'Organ failure persisting over 48 hours defines severe pancreatitis.', 'GI, Endocrine & Metabolic'),
(66, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Cullen''s sign in acute pancreatitis is:', '["Periumbilical bruising from retroperitoneal bleeding", "Shoulder tip pain from diaphragm irritation", "Flank bruising from retroperitoneal bleeding", "Jaundice from compression of the bile duct"]'::jsonb, 0, 'Grey Turner''s sign is flank bruising.', 'GI, Endocrine & Metabolic'),
(67, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Infected pancreatic necrosis is suspected when:', '["A rise in serum amylase on the first day of illness", "Pain that improves when oral feeding is restarted", "A normal blood glucose throughout the admission", "Fever and worsening organs at 7–10 days, with gas on CT"]'::jsonb, 3, 'Drainage or necrosectomy and antibiotics are required.', 'GI, Endocrine & Metabolic'),
(68, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Fournier''s gangrene is:', '["Clostridial gas gangrene of the thigh", "Necrotising fasciitis of the perineum", "Ischaemic colitis affecting the rectum", "Dry gangrene of the toes in diabetes"]'::jsonb, 1, 'It is a surgical emergency; diabetes and immunosuppression are risk factors.', 'GI, Endocrine & Metabolic'),
(69, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'The LRINEC score is used to:', '["Grade the depth of pressure ulcers", "Assess delirium in ventilated ICU patients", "Predict post-operative nausea and vomiting", "Help identify necrotising fasciitis from blood tests"]'::jsonb, 3, 'It uses CRP, WBC, haemoglobin, sodium, creatinine and glucose; a high score raises suspicion.', 'GI, Endocrine & Metabolic'),
(70, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'After TURP, a three-way catheter blocks with clots and the patient has bladder spasm. The nurse should:', '["Clamp the drainage tubing for one hour", "Give a diuretic to flush the bladder through", "Stop irrigation, wash out per protocol, inform the doctor", "Increase the irrigation rate to force the clot out"]'::jsonb, 2, 'Continuing irrigation into a blocked bladder risks rupture.', 'GI, Endocrine & Metabolic'),
(71, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Acute urinary retention from benign prostatic hyperplasia is relieved by:', '["Oral analgesics and a warm bath only", "Restricting oral fluids until it settles", "Urethral catheter, or suprapubic if urethral fails", "IV fluids with a dose of IV furosemide"]'::jsonb, 2, 'Record the residual volume; watch for post-obstructive diuresis.', 'GI, Endocrine & Metabolic'),
(72, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Polyneuropathy in a diabetic ICU patient most increases the risk of:', '["Hyperglycaemia only, without skin risk", "Raised intracranial pressure", "Pressure injury and silent foot ulceration", "Severe hypertension and stroke"]'::jsonb, 2, 'Loss of sensation means the patient does not feel pressure or injury.', 'GI, Endocrine & Metabolic'),
(73, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'A Category 4 pressure ulcer involves:', '["Partial-thickness loss with a shallow, open ulcer", "Intact skin with non-blanching redness over bone", "Full-thickness loss with exposed bone, tendon or muscle", "Full-thickness skin loss with only fat visible"]'::jsonb, 2, 'Unstageable ulcers have the base covered by slough or eschar.', 'GI, Endocrine & Metabolic'),
(74, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Prone positioning for ARDS increases the risk of pressure injury to the:', '["Back of the head and shoulders only", "Elbows and wrists only", "Face, chest, knees and iliac crests", "Heels, sacrum and occiput only"]'::jsonb, 2, 'Padding and position changes every 2–4 hours are used.', 'GI, Endocrine & Metabolic'),
(75, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'The cosyntropin (synacthen) stimulation test assesses:', '["Thyroid hormone production", "Adrenal cortisol response to ACTH", "Growth hormone release", "Insulin secretion by the pancreas"]'::jsonb, 1, 'A poor rise in cortisol suggests adrenal insufficiency.', 'GI, Endocrine & Metabolic'),
(76, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Relative adrenal insufficiency in septic shock is suspected when:', '["The blood pressure responds well to the first fluid bolus", "The patient has hyperkalaemia with no hypotension", "The blood glucose is persistently high on insulin", "Hypotension persists despite fluids and rising vasopressors"]'::jsonb, 3, 'Hydrocortisone 200 mg/day is given in refractory septic shock.', 'GI, Endocrine & Metabolic'),
(77, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Obese ICU patients should have drug doses for some agents (e.g. propofol infusion) calculated on:', '["Height only", "Age only", "Total body weight in every case", "Ideal or adjusted body weight"]'::jsonb, 3, 'Lipid-soluble drugs may accumulate; follow pharmacy guidance.', 'GI, Endocrine & Metabolic'),
(78, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Equipment needed for a critically ill obese patient includes:', '["Bariatric bed, larger BP cuffs and lifting aids", "Only a larger-size urinary catheter", "No special equipment for these patients", "A standard bed with a small BP cuff"]'::jsonb, 0, 'Incorrect cuff size gives falsely high BP readings.', 'GI, Endocrine & Metabolic'),
(79, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'Hypothermia in trauma (accidental hypothermia) is considered severe below:', '["34 °C", "28 °C", "35 °C", "32 °C"]'::jsonb, 1, 'Severe hypothermia risks VF; patients should be handled gently and rewarmed actively.', 'GI, Endocrine & Metabolic'),
(80, 'Abdomen, Urology, Skin and Metabolic Emergencies', 'A hypothermic patient (30 °C) in cardiac arrest should have:', '["CPR continued while rewarming; ''not dead until warm and dead''", "Adrenaline every 1 minute at full dose", "CPR stopped immediately as futile", "Defibrillation repeated every minute without rewarming"]'::jsonb, 0, 'Drugs are withheld below 30 °C and spaced out until 35 °C.', 'GI, Endocrine & Metabolic'),
(81, 'Neonatal Critical Care II', 'In neonatal resuscitation, after drying and stimulating, the next assessment is:', '["Core temperature only", "Non-invasive blood pressure", "Breathing and heart rate", "Blood glucose level"]'::jsonb, 2, 'If apnoeic or HR below 100, start inflation breaths and ventilation.', 'Obstetric & Neonatal'),
(82, 'Neonatal Critical Care II', 'Inflation breaths for a term newborn are given:', '["Five breaths, each held for 2–3 seconds", "Ten breaths at a rate of 60 per minute", "Two quick breaths, each lasting 1 second", "One sustained breath held for 10 seconds"]'::jsonb, 0, 'They open fluid-filled lungs; then ventilate at 30–60 breaths per minute.', 'Obstetric & Neonatal'),
(83, 'Neonatal Critical Care II', 'Room air is used at the start of term newborn resuscitation because:', '["It is cheaper than oxygen", "Oxygen is never needed in newborns", "It increases the heart rate faster", "Excess oxygen may harm the newborn"]'::jsonb, 3, 'Oxygen is titrated to target pre-ductal SpO₂ on the right hand.', 'Obstetric & Neonatal'),
(84, 'Neonatal Critical Care II', 'A newborn with meconium-stained liquor who is not breathing should first receive:', '["IV adrenaline before ventilation is attempted", "Inflation breaths and ventilation; suction only if blocked", "Routine deep tracheal suction before any breaths", "Chest compressions started immediately at birth"]'::jsonb, 1, 'Routine tracheal suction is no longer recommended.', 'Obstetric & Neonatal'),
(85, 'Neonatal Critical Care II', 'Physiological jaundice differs from pathological jaundice because physiological jaundice:', '["Appears after 24 hours and resolves by 2 weeks", "Requires exchange transfusion in all cases", "Is associated with a conjugated bilirubin rise", "Appears within the first 24 hours"]'::jsonb, 0, 'Jaundice in the first 24 hours is always pathological.', 'Obstetric & Neonatal'),
(86, 'Neonatal Critical Care II', 'During phototherapy, the nurse should:', '["Cover the eyes, expose the skin, watch temperature and fluids", "Stop all feeds while the lights are on", "Cover the whole body with a blanket to keep warm", "Avoid turning the baby during phototherapy"]'::jsonb, 0, 'Phototherapy increases insensible water loss.', 'Obstetric & Neonatal'),
(87, 'Neonatal Critical Care II', 'During exchange transfusion, blood glucose is checked because:', '["Hypoglycaemia can follow the high glucose in citrated blood", "Glucose has no relevance during an exchange transfusion", "Hyperglycaemia always persists for several days afterwards", "The baby cannot be fed for a week after the procedure"]'::jsonb, 0, 'Calcium, potassium and blood gases are also monitored.', 'Obstetric & Neonatal'),
(88, 'Neonatal Critical Care II', 'The umbilical venous catheter used for exchange transfusion is inserted:', '["Into the radial artery at the wrist", "Into the umbilical vein, aseptically", "Into a scalp vein over the temple", "Into the femoral vein in the groin"]'::jsonb, 1, 'Its position is confirmed and secured; complications include infection and portal vein thrombosis.', 'Obstetric & Neonatal'),
(89, 'Neonatal Critical Care II', 'Late-onset neonatal sepsis (after 72 hours) is commonly caused by:', '["Coagulase-negative staphylococci and Gram-negative bacteria", "Malaria parasites transmitted in the unit", "Rotavirus, in all babies with late sepsis", "Group B Streptococcus from the mother in every case"]'::jsonb, 0, 'Central lines and prolonged admission increase the risk.', 'Obstetric & Neonatal'),
(90, 'Neonatal Critical Care II', 'The most effective way to reduce neonatal infection in a special care baby unit is:', '["Bathing every baby twice a day with antiseptic", "Keeping the mothers out of the unit completely", "Routine prophylactic antibiotics for all babies", "Hand hygiene before and after every baby contact"]'::jsonb, 3, 'Breast milk and kangaroo care also reduce infection.', 'Obstetric & Neonatal'),
(91, 'Neonatal Critical Care II', 'Kangaroo mother care is beneficial for preterm babies because it:', '["It is used only for well term babies", "It increases the risk of hypothermia", "Warmth, breastfeeding and less infection", "It replaces the need for any feeding"]'::jsonb, 2, 'Skin-to-skin contact stabilises temperature, breathing and heart rate.', 'Obstetric & Neonatal'),
(92, 'Neonatal Critical Care II', 'Feeding a preterm baby of 30 weeks with no sucking reflex is best done by:', '["Orogastric or nasogastric feeds of breast milk", "No feeds until 36 weeks'' corrected age", "Spoon feeding of standard infant formula", "Bottle feeding with a large, fast-flow teat"]'::jsonb, 0, 'The suck-swallow-breathe coordination usually develops around 32–34 weeks.', 'Obstetric & Neonatal'),
(93, 'Neonatal Critical Care II', 'Necrotising enterocolitis in a preterm baby presents with:', '["Constipation only, with normal feeding", "Projectile non-bilious vomiting after feeds", "Distension, bloody stools and bilious aspirates", "Watery stools with a soft, normal abdomen"]'::jsonb, 2, 'Stop feeds, decompress, give antibiotics; surgery for perforation.', 'Obstetric & Neonatal'),
(94, 'Neonatal Critical Care II', 'Respiratory distress syndrome in preterm babies is caused by:', '["Excess lung fluid at term", "Meconium aspiration", "Surfactant deficiency", "Pneumothorax only"]'::jsonb, 2, 'Antenatal steroids and surfactant therapy reduce severity.', 'Obstetric & Neonatal'),
(95, 'Neonatal Critical Care II', 'Signs of respiratory distress in a newborn include:', '["Grunting, flaring, recession, rate over 60/min", "Hiccups and sneezing only", "Normal breathing with a loud cry", "Rate under 20/min with a pink colour"]'::jsonb, 0, 'Grunting maintains end-expiratory pressure.', 'Obstetric & Neonatal'),
(96, 'Neonatal Critical Care II', 'The normal blood glucose of a newborn should be maintained above:', '["10 mmol/L (about 180 mg/dL)", "0.5 mmol/L (about 9 mg/dL)", "1.0 mmol/L (about 18 mg/dL)", "2.6 mmol/L (about 47 mg/dL)"]'::jsonb, 3, 'Hypoglycaemia can cause brain injury; early feeding and IV dextrose are used.', 'Obstetric & Neonatal'),
(97, 'Neonatal Critical Care II', 'Neonatal hypoglycaemia is treated with an IV bolus of:', '["1 mL/kg of 5% dextrose", "5 mL/kg of 25% dextrose", "2 mL/kg of 10% dextrose", "10 mL/kg of 50% dextrose"]'::jsonb, 2, 'Higher concentrations are hypertonic and damage veins.', 'Obstetric & Neonatal'),
(98, 'Neonatal Critical Care II', 'A ''safe sleep'' environment for infants in hospital should include:', '["Firm flat mattress, on the back, no loose bedding", "Sharing a bed with an adult for warmth", "Prone position with the head turned to the side", "Soft pillows and toys in the cot for comfort"]'::jsonb, 0, 'These reduce the risk of sudden infant death.', 'Obstetric & Neonatal'),
(99, 'Neonatal Critical Care II', 'An apnoea monitor alarm sounds on a preterm baby with HR 70 and dusky colour. The nurse''s first action is:', '["Stimulate gently; if no breathing, start bag-mask ventilation", "Wait 5 minutes to see whether the apnoea resolves alone", "Give a feed by NG tube to stimulate the baby to breathe", "Silence the alarm and continue routine observation"]'::jsonb, 0, 'Apnoea of prematurity is treated with caffeine citrate.', 'Obstetric & Neonatal'),
(100, 'Neonatal Critical Care II', 'Caffeine citrate is used in preterm babies to:', '["Prevent neonatal hypoglycaemia", "Sedate the restless baby", "Treat apnoea of prematurity", "Treat neonatal jaundice"]'::jsonb, 2, 'It is given once daily; tachycardia and feed intolerance are side effects.', 'Obstetric & Neonatal'),
(101, 'Paediatric Critical Care II', 'A lumbar puncture is generally avoided or delayed in a patient with suspected meningitis if there are signs of raised intracranial pressure, primarily because of the risk of:', '["No particular risk exists in this situation at all", "Brain herniation from the pressure change of CSF removal", "A reduced risk of spreading the infection", "Improvement in the patient''s neurological outcome"]'::jsonb, 1, 'Lumbar puncture in the presence of significantly raised ICP risks precipitating brain herniation due to the pressure gradient created by CSF removal — imaging is typically obtained first if raised ICP is suspected.', 'Paediatric'),
(102, 'Paediatric Critical Care II', 'A patient with meningitis develops photophobia, neck stiffness, and a non-blanching purpuric rash. The nurse should recognise the rash as a red flag suggesting:', '["Possible meningococcal sepsis needing urgent antibiotics", "A simple allergic reaction to the antibiotics given", "A normal viral rash with no clinical urgency", "A rash unrelated to the meningitis diagnosis"]'::jsonb, 0, 'A non-blanching purpuric rash with meningitis symptoms is a red flag for meningococcal sepsis, a rapidly progressive, life-threatening condition requiring immediate antibiotic treatment.', 'Paediatric'),
(103, 'Paediatric Critical Care II', 'A child with severe dehydration (10% or more) needs initial IV fluid of:', '["Oral rehydration fluids only, by cup or spoon", "20 mL/kg boluses of 0.9% saline, reassessing each time", "5 mL/kg of 3% hypertonic saline as a single bolus", "50 mL/kg of 5% dextrose over 10 minutes, once"]'::jsonb, 1, 'Then replace the deficit and maintenance over 24–48 hours.', 'Paediatric'),
(104, 'Paediatric Critical Care II', 'For a 15 kg child, the maintenance fluid by the Holliday–Segar method is:', '["2000 mL per 24 hours", "750 mL per 24 hours", "1500 mL per 24 hours", "1250 mL per 24 hours"]'::jsonb, 3, '100 mL/kg for the first 10 kg (1000 mL) + 50 mL/kg for the next 5 kg (250 mL).', 'Paediatric'),
(105, 'Paediatric Critical Care II', 'A child with croup has stridor at rest and recession. The first-line treatment is:', '["Dexamethasone, plus nebulised adrenaline if severe", "Sedation with IV diazepam to calm the child", "Examining the throat with a tongue spatula", "Oral antibiotics only for five days"]'::jsonb, 0, 'Keep the child calm; distress worsens the obstruction.', 'Paediatric'),
(106, 'Paediatric Critical Care II', 'Epiglottitis differs from croup because the child:', '["Has a barking cough with a mild fever at night", "Has a gradual onset of symptoms over a week", "Is toxic, drooling and sitting forward, with little cough", "Improves rapidly with steam inhalation at home"]'::jsonb, 2, 'Do not examine the throat; secure the airway in theatre.', 'Paediatric'),
(107, 'Paediatric Critical Care II', 'A child with acute severe asthma becomes quiet with a ''silent chest'' and drowsiness. This indicates:', '["A normal response to inhaled salbutamol", "That the child is ready for discharge home", "Life-threatening asthma needing immediate escalation", "Improvement in the attack after nebulisers"]'::jsonb, 2, 'Prepare for IV therapy and possible intubation.', 'Paediatric'),
(108, 'Paediatric Critical Care II', 'A febrile convulsion lasting more than 5 minutes is treated with:', '["Restraining the child firmly during the fit", "Buccal midazolam or rectal diazepam, then IV lorazepam", "Oral paracetamol only once the child wakes", "Cold water immersion until the fit stops"]'::jsonb, 1, 'Protect the airway and check glucose.', 'Paediatric'),
(109, 'Paediatric Critical Care II', 'Intussusception that has caused peritonitis or perforation is treated by:', '["Oral laxatives and a high-fibre diet", "Observation for 24 hours with IV fluids", "Air enema reduction under X-ray screening", "Surgical laparotomy with reduction or resection"]'::jsonb, 3, 'Enema is contraindicated if perforation or peritonitis is present.', 'Paediatric'),
(110, 'Paediatric Critical Care II', 'In a child with suspected appendicitis, the ICU nurse should anticipate perforation if:', '["There is mild nausea only, without vomiting", "The child becomes hungry and asks for food", "Pain becomes generalised with high fever and rigidity", "The pain moves from the umbilicus to the right iliac fossa"]'::jsonb, 2, 'Young children perforate early because the omentum is less developed.', 'Paediatric'),
(111, 'Paediatric Critical Care II', 'In an infant with Hirschsprung-associated enterocolitis, the priority is:', '["Oral laxatives only, given twice daily", "Fluid resuscitation, antibiotics and rectal washouts", "A high-fibre diet and extra oral fluids", "Immediate discharge with outpatient follow-up"]'::jsonb, 1, 'Enterocolitis is the main cause of death in Hirschsprung''s disease.', 'Paediatric'),
(112, 'Paediatric Critical Care II', 'A child with sickle cell disease and sudden severe anaemia with a rapidly enlarging spleen has:', '["Aplastic crisis from parvovirus", "Acute splenic sequestration crisis", "Vaso-occlusive bone crisis", "Haemolytic crisis from malaria"]'::jsonb, 1, 'It can cause shock and death; urgent transfusion is needed.', 'Paediatric'),
(113, 'Paediatric Critical Care II', 'Parvovirus B19 infection in sickle cell disease causes:', '["Polycythaemia with a high haematocrit", "Aplastic crisis with very low reticulocytes", "Acute chest syndrome only, with hypoxia", "Splenic sequestration with a big spleen"]'::jsonb, 1, 'Red cell production stops temporarily; transfusion may be required.', 'Paediatric'),
(114, 'Paediatric Critical Care II', 'Children with HIV in ICU commonly present with:', '["Hypertension and haemorrhagic stroke", "Severe pneumonia, including Pneumocystis", "Kidney stones and renal colic", "Gallstones and acute cholecystitis"]'::jsonb, 1, 'PCP is treated with high-dose cotrimoxazole and steroids.', 'Paediatric'),
(115, 'Paediatric Critical Care II', 'Cotrimoxazole prophylaxis in HIV-exposed infants prevents:', '["HIV transmission from the mother", "Neonatal jaundice and kernicterus", "Pneumocystis pneumonia and other infections", "Malaria completely, in all infants"]'::jsonb, 2, 'It is started at 6 weeks of age.', 'Paediatric'),
(116, 'Paediatric Critical Care II', 'The incubation period of Lassa fever is about:', '["6–21 days", "1–2 hours", "2 months", "1 year"]'::jsonb, 0, 'Early symptoms are non-specific: fever, sore throat and malaise.', 'Paediatric'),
(117, 'Paediatric Critical Care II', 'A health worker has a needle-stick injury from a Lassa fever patient. The recommended action is:', '["Report at once and start post-exposure ribavirin per policy", "Take paracetamol only and continue the shift", "Ignore it unless symptoms appear within the next month", "Continue working without reporting to avoid panic"]'::jsonb, 0, 'Close monitoring for 21 days is also required.', 'Paediatric'),
(118, 'Paediatric Critical Care II', 'Safe burial of a patient who died of Ebola requires:', '["Trained teams with full PPE; relatives do not wash the body", "Family members washing and dressing the body at home", "Keeping the body at home for several days for mourning", "Open-casket viewing at the funeral service"]'::jsonb, 0, 'Dead bodies remain highly infectious.', 'Paediatric'),
(119, 'Paediatric Critical Care II', 'Leukaemia in children most commonly presents with:', '["Jaundice and generalised itching", "Hypertension and persistent headaches", "Weight gain and generalised oedema", "Pallor, fever, bruising and bone pain"]'::jsonb, 3, 'Acute lymphoblastic leukaemia is the commonest childhood cancer.', 'Paediatric'),
(120, 'Paediatric Critical Care II', 'A child receiving chemotherapy has fever 38.5 °C. The nurse should first:', '["Send the child home with oral antibiotics", "Give paracetamol and wait to see if the fever settles", "Give a live vaccine to boost the immune system", "Take blood cultures and give IV antibiotics within 1 hour"]'::jsonb, 3, 'Neutropenic sepsis can kill rapidly.', 'Paediatric'),
(121, 'Obstetric Critical Care II', 'Therapeutic amnioreduction may be performed for polyhydramnios when:', '["There is a placenta praevia on scan", "The fetus is growth-restricted on scan", "The mother has severe breathlessness or discomfort", "The amniotic fluid index measures 10 cm"]'::jsonb, 2, 'Rapid removal risks abruption, so fluid is removed slowly.', 'Obstetric & Neonatal'),
(122, 'Obstetric Critical Care II', 'Indomethacin may reduce polyhydramnios by:', '["Increasing maternal urine output", "Increasing fetal swallowing", "Causing uterine contractions", "Reducing fetal urine production"]'::jsonb, 3, 'It can cause premature closure of the fetal ductus arteriosus, so use is limited.', 'Obstetric & Neonatal'),
(123, 'Obstetric Critical Care II', 'Oligohydramnios is associated with:', '["Renal agenesis, placental insufficiency, ruptured membranes", "Fetal oesophageal atresia with absent stomach bubble", "Poorly controlled maternal diabetes with macrosomia", "Fetal anencephaly with failure of swallowing"]'::jsonb, 0, 'It can cause pulmonary hypoplasia and limb deformities.', 'Obstetric & Neonatal'),
(124, 'Obstetric Critical Care II', 'Symmetrical IUGR is more commonly due to:', '["A post-term pregnancy beyond 42 completed weeks", "Early insults, e.g. chromosomal anomaly or congenital infection", "Late placental insufficiency in the third trimester", "Maternal pre-eclampsia developing after 34 weeks"]'::jsonb, 1, 'The head and abdomen are both small.', 'Obstetric & Neonatal'),
(125, 'Obstetric Critical Care II', 'Fetal surveillance in IUGR includes:', '["Urine dipstick for protein at each visit only", "No monitoring until delivery is planned", "Maternal weight at each antenatal visit only", "Serial growth scans, umbilical Doppler and CTG"]'::jsonb, 3, 'Abnormal Doppler guides the timing of delivery.', 'Obstetric & Neonatal'),
(126, 'Obstetric Critical Care II', 'Antenatal corticosteroids before preterm delivery are given mainly to:', '["Mature the fetal lungs and reduce RDS", "Prevent maternal infection after delivery", "Stop uterine contractions in preterm labour", "Treat maternal hypertension in pre-eclampsia"]'::jsonb, 0, 'Betamethasone or dexamethasone is given 24 hours to 7 days before delivery.', 'Obstetric & Neonatal'),
(127, 'Obstetric Critical Care II', 'Magnesium sulphate given before very preterm birth (under 32 weeks) protects the baby against:', '["Neonatal sepsis", "Respiratory distress syndrome", "Neonatal jaundice", "Cerebral palsy"]'::jsonb, 3, 'It is a neuroprotective agent.', 'Obstetric & Neonatal'),
(128, 'Obstetric Critical Care II', 'Signs of uterine rupture during labour include:', '["A rising blood pressure with headache and visual change", "A painless vaginal discharge with normal CTG", "Sudden pain, contractions stop, maternal shock, fetal distress", "A gradual increase in contraction strength only"]'::jsonb, 2, 'Risk is higher after previous caesarean section and with oxytocin use.', 'Obstetric & Neonatal'),
(129, 'Obstetric Critical Care II', 'Septic shock in a postnatal woman with a retained placenta requires:', '["An oxytocin infusion alone, with observation", "Resuscitation, antibiotics and evacuation of retained products", "Waiting for spontaneous passage of the products", "Antibiotics alone, without any surgical procedure"]'::jsonb, 1, 'Source control is essential in sepsis.', 'Obstetric & Neonatal'),
(130, 'Obstetric Critical Care II', 'Breast abscess in a postnatal woman is managed by:', '["Observation without any treatment for a week", "Stopping breastfeeding on both sides permanently", "Cold compresses only, without antibiotics", "Drainage, antibiotics and continued milk removal"]'::jsonb, 3, 'Staphylococcus aureus is the usual cause.', 'Obstetric & Neonatal'),
(131, 'Obstetric Critical Care II', 'The ''4 Ts'' of postpartum haemorrhage are:', '["Tests, Transfusion, Treatment, Transfer", "Tachycardia, Tachypnoea, Temperature, Thirst", "Tone, Trauma, Tissue, Thrombin", "Temperature, Time, Tachycardia, Tension"]'::jsonb, 2, 'Uterine atony (tone) is the commonest cause.', 'Obstetric & Neonatal'),
(132, 'Obstetric Critical Care II', 'Tranexamic acid in postpartum haemorrhage should be given:', '["Within 3 hours of birth", "Only after 24 hours", "Only if the patient is not bleeding", "Only after hysterectomy"]'::jsonb, 0, 'The WOMAN trial showed reduced deaths from bleeding.', 'Obstetric & Neonatal'),
(133, 'Obstetric Critical Care II', 'A ruptured ectopic pregnancy with shock requires:', '["Observation with a repeat scan in 48 hours", "Methotrexate injection and outpatient review", "Oral analgesia and discharge home", "Resuscitation with blood and urgent laparotomy"]'::jsonb, 3, 'It is a surgical emergency.', 'Obstetric & Neonatal'),
(134, 'Obstetric Critical Care II', 'HELLP syndrome stands for:', '["Haemolysis, Elevated Liver enzymes, Low Platelets", "Haemorrhage, Electrolytes, Lactate, Pressure", "High Enzymes, Low Lipids, Proteinuria", "Hypertension, Eclampsia, Liver failure, Pain"]'::jsonb, 0, 'It is a severe form of pre-eclampsia; delivery is the definitive treatment.', 'Obstetric & Neonatal'),
(135, 'Obstetric Critical Care II', 'Eclamptic seizures are treated first with:', '["Diazepam 10 mg IV, repeated as needed", "Paracetamol IV and cooling only", "Magnesium sulphate 4 g IV loading dose", "Phenytoin infusion over 30 minutes"]'::jsonb, 2, 'Magnesium is superior to diazepam and phenytoin in eclampsia.', 'Obstetric & Neonatal'),
(136, 'Obstetric Critical Care II', 'Severe hypertension in pregnancy (BP 160/110) should be treated urgently with:', '["Large doses of IV furosemide every 6 hours", "An ACE inhibitor such as lisinopril by mouth", "IV labetalol, IV hydralazine or oral nifedipine", "No treatment at all until after the delivery"]'::jsonb, 2, 'This reduces the risk of maternal stroke.', 'Obstetric & Neonatal'),
(137, 'Obstetric Critical Care II', 'A woman in the third trimester with sudden breathlessness, chest pain and tachycardia most likely has:', '["Pulmonary embolism", "Normal pregnancy breathlessness", "Mild asthma", "Heartburn"]'::jsonb, 0, 'Pregnancy is a hypercoagulable state; LMWH is the treatment.', 'Obstetric & Neonatal'),
(138, 'Obstetric Critical Care II', 'A pregnant woman collapses. The nurse should immediately:', '["Give oral fluids and raise the legs", "Call for help, start CPR, displace the uterus to the left", "Lie her flat on her back without any tilt", "Wait for the obstetrician before starting CPR"]'::jsonb, 1, 'Perimortem caesarean is performed within 5 minutes if no ROSC.', 'Obstetric & Neonatal'),
(139, 'Obstetric Critical Care II', 'The main cause of maternal death in Nigeria is:', '["Diabetes in pregnancy", "Postpartum haemorrhage", "Migraine with aura", "Acute severe asthma"]'::jsonb, 1, 'Eclampsia, sepsis and obstructed labour are other leading causes.', 'Obstetric & Neonatal'),
(140, 'Obstetric Critical Care II', 'Puerperal pyrexia is defined as a temperature of 38 °C or above:', '["Only after the 6-week postnatal check", "Only during the first stage of labour", "Within 14 days after childbirth or miscarriage", "Only in the first hour after delivery"]'::jsonb, 2, 'It requires investigation for infection, including the genital tract, breast and urine.', 'Obstetric & Neonatal'),
(141, 'Ethico-legal Issues and Documentation in Critical Care II', 'Brain stem death testing can be performed only when:', '["The patient has been in the ICU for a full 24 hours on the ventilator", "The family has formally requested that the tests should be performed", "The patient is still receiving sedative infusions at a reduced rate", "Reversible causes such as drugs, hypothermia and metabolic disorders are excluded"]'::jsonb, 3, 'Two senior doctors perform the tests; the nurse supports the family.', 'Ethics, Law & Management'),
(142, 'Ethico-legal Issues and Documentation in Critical Care II', 'Withdrawal of life-sustaining treatment in ICU should involve:', '["Team consensus, family discussion and a documented comfort plan", "No written record, to protect the staff involved", "Stopping all care, including analgesia and sedation", "A single nurse deciding alone during the night shift"]'::jsonb, 0, 'Comfort, dignity and family support remain priorities.', 'Ethics, Law & Management'),
(143, 'Ethico-legal Issues and Documentation in Critical Care II', 'A competent Jehovah''s Witness refuses blood transfusion while bleeding in ICU. The nurse should:', '["Discharge the patient from ICU to the ward", "Transfuse the blood secretly while the patient sleeps", "Sedate the patient and then give the transfusion", "Respect the refusal, document it and support alternatives"]'::jsonb, 3, 'Competent adults can refuse treatment even if it leads to death.', 'Ethics, Law & Management'),
(144, 'Ethico-legal Issues and Documentation in Critical Care II', 'For a child of Jehovah''s Witness parents who needs life-saving blood, the team usually:', '["Seeks a court order, or acts in the child''s best interests in an emergency", "Accepts the parents'' refusal even though the child will probably die", "Asks the young child to make the final decision about the blood alone", "Gives no further treatment of any kind to the child until discharge"]'::jsonb, 0, 'The child''s welfare is paramount.', 'Ethics, Law & Management'),
(145, 'Ethico-legal Issues and Documentation in Critical Care II', 'The legal age of consent for medical treatment in Nigeria is generally:', '["18 years", "14 years", "12 years", "21 years"]'::jsonb, 0, 'Emergency treatment of minors may proceed in their best interests if parents are not available.', 'Ethics, Law & Management'),
(146, 'Ethico-legal Issues and Documentation in Critical Care II', 'A nurse gives the wrong drug to an ICU patient without harm. The correct action is to:', '["Say nothing, because the patient came to no harm", "Inform the doctor, monitor, document and report the incident", "Change the drug chart to hide the administration error", "Ask a colleague to sign the chart for the wrong drug"]'::jsonb, 1, 'Open disclosure and reporting improve safety.', 'Ethics, Law & Management'),
(147, 'Ethico-legal Issues and Documentation in Critical Care II', 'Patient information may be shared without consent when:', '["A journalist requests it for a story", "The patient is a well-known public figure", "A friend of the patient calls the unit", "Required by law, e.g. notifiable diseases"]'::jsonb, 3, 'Only necessary information is shared.', 'Ethics, Law & Management'),
(148, 'Ethico-legal Issues and Documentation in Critical Care II', 'Taking photographs of an ICU patient for social media is:', '["A breach of confidentiality and misconduct", "Encouraged to support health education", "Acceptable if the patient''s face is covered", "Acceptable with a relative''s verbal permission"]'::jsonb, 0, 'The NMCN can discipline nurses for this.', 'Ethics, Law & Management'),
(149, 'Ethico-legal Issues and Documentation in Critical Care II', 'Documentation in the ICU chart should be:', '["Accurate, timely, legible, signed, never erased", "Written up at the end of the working week", "Written by any staff member for others", "Corrected neatly using correction fluid"]'::jsonb, 0, 'Errors are crossed with a single line, dated and signed.', 'Ethics, Law & Management'),
(150, 'Ethico-legal Issues and Documentation in Critical Care II', 'A late entry in the patient record should be:', '["Backdated to the time the event actually happened", "Squeezed in between the earlier lines of the notes", "Written in pencil so it can be changed later", "Marked as a late entry, with the current date and time"]'::jsonb, 3, 'This preserves the integrity of the record.', 'Ethics, Law & Management'),
(151, 'Ethico-legal Issues and Documentation in Critical Care II', 'The doctrine of informed consent requires disclosure of:', '["Nature, benefits, material risks and alternatives", "Only the time and place of the procedure", "Only the cost of the procedure to the family", "Only the name of the doctor doing the procedure"]'::jsonb, 0, 'Material risks are those a reasonable patient would want to know.', 'Ethics, Law & Management'),
(152, 'Ethico-legal Issues and Documentation in Critical Care II', 'Restraining an agitated ICU patient without assessment or orders may constitute:', '["An example of beneficence", "Battery and false imprisonment", "Good, safe nursing practice", "An example of fidelity"]'::jsonb, 1, 'Restraints require assessment, documentation and regular review.', 'Ethics, Law & Management'),
(153, 'Ethico-legal Issues and Documentation in Critical Care II', 'When a patient dies in ICU after an assault, the case must be reported to:', '["No one, as the patient has died in hospital", "Only the family, who decide what happens", "The police or coroner, as a medico-legal case", "The hospital chaplain and the mortuary only"]'::jsonb, 2, 'Medico-legal deaths require post-mortem examination.', 'Ethics, Law & Management'),
(154, 'Ethico-legal Issues and Documentation in Critical Care II', 'An ICU nurse is asked to give evidence in court. She should:', '["Refuse to attend court without any reason", "Use her contemporaneous notes and state facts honestly", "Give expert opinions outside her area of competence", "Rewrite the notes before attending court"]'::jsonb, 1, 'Good documentation is the best defence.', 'Ethics, Law & Management'),
(155, 'Ethico-legal Issues and Documentation in Critical Care II', 'A patient with animal bite and hydrophobia, agitation and spasms most likely has:', '["Clinical rabies, which is almost always fatal", "Simple anxiety after the dog bite", "Bacterial meningitis from the wound", "Tetanus with lockjaw from a wound"]'::jsonb, 0, 'Care is supportive; staff should use barrier precautions.', 'Ethics, Law & Management'),
(156, 'Ethico-legal Issues and Documentation in Critical Care II', 'Respect for autonomy is best shown in ICU by:', '["Following the family''s wishes over the patient''s", "Involving competent patients in decisions", "Making all the decisions for the patient", "Withholding information to avoid worry"]'::jsonb, 1, 'Information is given in a way the patient understands.', 'Ethics, Law & Management'),
(157, 'Ethico-legal Issues and Documentation in Critical Care II', 'Justice in ICU resource allocation means:', '["First come, first served, whatever the need", "Allocating beds by need and likely benefit", "Admitting only patients who can pay in advance", "Admitting friends and relatives of staff first"]'::jsonb, 1, 'Triage policies support fair allocation.', 'Ethics, Law & Management'),
(158, 'Ethico-legal Issues and Documentation in Critical Care II', 'The Good Samaritan principle does NOT protect a nurse who:', '["Provides first aid in good faith at the scene", "Calls for emergency help and ambulance services", "Stays with the casualty until help arrives", "Acts with gross negligence or beyond her training"]'::jsonb, 3, 'Help must be reasonable and within competence.', 'Ethics, Law & Management'),
(159, 'Ethico-legal Issues and Documentation in Critical Care II', 'Handing over a patient at the end of the shift should include:', '["Personal opinions and gossip about the family", "Diagnosis, status, treatments, risks and pending tasks", "Only the bed number and the consultant''s name", "Only the patient''s name and the hospital number"]'::jsonb, 1, 'Structured handover (e.g. SBAR) reduces errors.', 'Ethics, Law & Management'),
(160, 'Ethico-legal Issues and Documentation in Critical Care II', 'Dispensing medications by a nurse without prescription in ICU is:', '["Outside her legal scope except under approved protocols", "Allowed for all drugs during the night shift", "Allowed whenever the patient asks for a drug", "Always allowed in any emergency situation"]'::jsonb, 0, 'Standing orders or protocols must be approved.', 'Ethics, Law & Management'),
(161, 'ICU Management, Quality and Safety II', 'The MOST appropriate leadership approach during a sudden cardiac arrest in the ICU is:', '["Democratic leadership by voting on interventions", "Autocratic leadership with clear, direct instructions", "Laissez-faire leadership", "Bureaucratic leadership without communication"]'::jsonb, 1, 'Clear, direct, autocratic leadership suits the urgency of a cardiac arrest response.', 'Ethics, Law & Management'),
(162, 'ICU Management, Quality and Safety II', 'A newly employed ICU nurse is unable to operate a mechanical ventilator safely. The nurse manager should FIRST:', '["Assign the nurse to independent ventilator care", "Arrange supervised training and assess competency", "Issue a written warning", "Transfer the nurse to another hospital"]'::jsonb, 1, 'Supervised training and competency assessment address a specific identified skill gap before independent practice resumes.', 'Ethics, Law & Management'),
(163, 'ICU Management, Quality and Safety II', 'The ICU manager notices an increase in medication errors during the night shift. The priority action is to:', '["Investigate root causes before corrective measures", "Report all of the nurses to the Nursing Council", "Suspend all of the night-duty nurses at once", "Reduce the number of patients admitted at night"]'::jsonb, 0, 'Investigating root causes before acting ensures corrective measures address the real underlying problem rather than just the symptom.', 'Ethics, Law & Management'),
(164, 'ICU Management, Quality and Safety II', 'Theory Y managers believe that staff:', '["Enjoy work, seek responsibility and self-direct", "Work only for money and fear punishment", "Cannot be trusted to make any decisions", "Dislike work and need close supervision"]'::jsonb, 0, 'McGregor''s Theory X assumes the opposite.', 'Ethics, Law & Management'),
(165, 'ICU Management, Quality and Safety II', 'Herzberg''s motivation-hygiene theory states that salary and working conditions are:', '["Factors that directly increase achievement and growth", "Completely irrelevant to job satisfaction in nursing", "Hygiene factors: they prevent dissatisfaction but do not motivate", "The main motivators that drive nurses to perform better"]'::jsonb, 2, 'Motivators include recognition, responsibility and achievement.', 'Ethics, Law & Management'),
(166, 'ICU Management, Quality and Safety II', 'Transformational leadership in ICU is characterised by:', '["Leaving staff to make all decisions on their own", "Focusing only on tasks, targets and rewards", "Strict rules with punishment for every mistake", "Inspiring a shared vision and encouraging growth"]'::jsonb, 3, 'It improves staff satisfaction and patient outcomes.', 'Ethics, Law & Management'),
(167, 'ICU Management, Quality and Safety II', 'A root cause analysis after a serious incident in ICU aims to:', '["Close the case as quickly as possible", "Identify system failures behind the event", "Find the individual who should be blamed", "Avoid informing the family of the event"]'::jsonb, 1, 'A just culture encourages reporting without fear.', 'Ethics, Law & Management'),
(168, 'ICU Management, Quality and Safety II', 'A ''near miss'' in ICU should be:', '["Hidden from the manager to avoid blame", "Reported, because it shows a risk of harm", "Ignored, because no harm occurred", "Reported only if the patient complains"]'::jsonb, 1, 'Near misses help prevent future incidents.', 'Ethics, Law & Management'),
(169, 'ICU Management, Quality and Safety II', 'The ICU nurse manager''s role in infection control includes:', '["Prescribing antibiotics for all patients", "Monitoring compliance, training staff, reporting rates", "Performing all invasive procedures personally", "Ignoring the results of infection audits"]'::jsonb, 1, 'Surveillance data guide improvements.', 'Ethics, Law & Management'),
(170, 'ICU Management, Quality and Safety II', 'When ICU beds are full and a critically ill patient needs admission, the manager should:', '["Refuse all communication until a bed becomes free", "Review patients for step-down and agree triage with the team", "Discharge the sickest patient to make room", "Admit the patient to a corridor without monitoring"]'::jsonb, 1, 'Escalation policies guide decisions.', 'Ethics, Law & Management'),
(171, 'ICU Management, Quality and Safety II', 'Early warning scores (e.g. NEWS2) help the ICU by:', '["Replacing routine nursing observations on the ward", "Assessing the performance of the nursing staff", "Calculating drug doses for critically ill patients", "Detecting ward deterioration and triggering early review"]'::jsonb, 3, 'Higher scores trigger escalation to the outreach or ICU team.', 'Ethics, Law & Management'),
(172, 'ICU Management, Quality and Safety II', 'An ICU orientation programme for new nurses should include:', '["Policies, equipment training, competencies and a preceptor", "Immediate sole care of two ventilated patients", "Only a short tour of the unit on the first day", "Reading the history of the hospital and its founders"]'::jsonb, 0, 'Competency-based orientation improves safety.', 'Ethics, Law & Management'),
(173, 'ICU Management, Quality and Safety II', 'Staff appraisal in ICU is mainly used to:', '["Replace formal training and education", "Reduce the salaries of underperforming staff", "Punish staff for errors made in the year", "Review performance and plan development"]'::jsonb, 3, 'Regular feedback improves practice.', 'Ethics, Law & Management'),
(174, 'ICU Management, Quality and Safety II', 'A care bundle in ICU is:', '["A group of patients cared for by one nurse", "A small set of evidence-based practices done together", "A collection of emergency drugs on a trolley", "A package of clean linen prepared for each bed"]'::jsonb, 1, 'Examples are VAP, CLABSI and sepsis bundles.', 'Ethics, Law & Management'),
(175, 'ICU Management, Quality and Safety II', 'Monitoring ICU quality indicators includes measuring:', '["The number of visitors to the unit each day", "The number of chairs available in the unit", "Unplanned readmissions, infection rates, mortality", "The colour and style of the staff uniforms"]'::jsonb, 2, 'Indicators guide improvement.', 'Ethics, Law & Management'),
(176, 'ICU Management, Quality and Safety II', 'Infection risk in an ICU is reduced in the design by:', '["No mechanical ventilation system at all", "Carpets on the floor to reduce noise", "Single isolation rooms and sinks by each bed", "Equipment shared between neighbouring beds"]'::jsonb, 2, 'Negative pressure rooms are used for airborne infections.', 'Ethics, Law & Management'),
(177, 'ICU Management, Quality and Safety II', 'Conflict between ICU nurses and doctors is best managed by:', '["Writing formal complaints without any discussion", "Avoiding each other for the rest of the shift", "Shouting at each other in front of the patients", "Open discussion focused on patient goals, with respect"]'::jsonb, 3, 'Collaboration improves teamwork.', 'Ethics, Law & Management'),
(178, 'ICU Management, Quality and Safety II', 'Disaster planning for an ICU includes:', '["No plans at all, because disasters are very rare", "Surge plans, staff call-in lists and equipment reserves", "Closing the unit completely during an emergency", "Leaving the decisions to visitors and relatives"]'::jsonb, 1, 'Regular drills test readiness.', 'Ethics, Law & Management'),
(179, 'ICU Management, Quality and Safety II', 'The ICU manager''s report on monthly activity should include:', '["Only the names of the patients admitted", "Only the birthdays of the staff that month", "Only the number of beds in the unit", "Admissions, outcomes, incidents, staffing, resources"]'::jsonb, 3, 'Reports inform planning and budgeting.', 'Ethics, Law & Management'),
(180, 'ICU Management, Quality and Safety II', 'Moral distress among ICU nurses often arises when:', '["They have adequate staffing on every shift", "They receive good training and support", "They are well paid for their work in ICU", "They cannot act on what they believe is right"]'::jsonb, 3, 'Ethics support and debriefing help.', 'Ethics, Law & Management'),
(181, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Which group of patients is classically at highest risk of Mendelson''s syndrome?', '["Patients who fasted appropriately before elective day-case surgery", "Well-controlled type 2 diabetics undergoing outpatient dental extraction", "Patients undergoing local anaesthesia for minor skin procedures", "Pregnant women undergoing emergency general anaesthesia"]'::jsonb, 3, 'Pregnant women have delayed gastric emptying, reduced lower oesophageal sphincter tone, and raised intra-abdominal pressure, making them classically the highest-risk group for aspiration under general anaesthesia.', 'Anaesthesia & Respiratory Care'),
(182, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Which precaution is most important in reducing the risk of anaesthetic death related to a difficult or failed airway?', '["Relying only on the surgeon''s assessment of the patient''s airway", "Proceeding with induction without any airway assessment to save time", "Thorough airway assessment and a ready difficult airway plan and equipment", "Avoiding pre-oxygenation so that the procedure is completed faster"]'::jsonb, 2, 'Systematic pre-anaesthetic airway assessment, along with a clear failed-airway algorithm and immediately available difficult airway equipment, significantly reduces the risk of catastrophic hypoxia from failed intubation.', 'Anaesthesia & Respiratory Care'),
(183, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'A comprehensive nutritional assessment typically integrates which four broad components?', '["Blood pressure, pulse, respiratory rate and core temperature", "Body weight and height only, used to calculate the BMI", "Anthropometry, biochemistry, clinical examination and dietary history", "Vital signs, medication list, allergy history and resuscitation status"]'::jsonb, 2, 'The classic ''ABCD'' framework of nutritional assessment includes Anthropometric measurements, Biochemical/laboratory data, Clinical examination, and Dietary history, providing a comprehensive picture of nutritional status.', 'Anaesthesia & Respiratory Care'),
(184, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Which of the following is an example of an anthropometric measurement used in nutritional assessment?', '["Mid-upper arm circumference", "Serum albumin level", "White blood cell count", "C-reactive protein level"]'::jsonb, 0, 'Anthropometric measurements assess body size and composition and include height, weight, BMI, mid-upper arm circumference, and triceps skinfold thickness.', 'Anaesthesia & Respiratory Care'),
(185, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'The usual first priority when aspiration of gastric content is witnessed during induction is:', '["Give IV steroids as the first and most important step", "Head-down tilt, suction and a cuffed tube to secure the airway", "Wait for a chest X-ray before doing anything else", "Sit the patient upright and give oral fluids to wash the throat"]'::jsonb, 1, 'Bronchoscopy may be needed for particulate matter; antibiotics are not routine for chemical pneumonitis.', 'Anaesthesia & Respiratory Care'),
(186, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Gastric residual volumes in an enterally fed ICU patient are:', '["Never checked in any enterally fed ICU patient", "The only reliable measure of feed tolerance in ICU", "Used to calculate the patient''s daily calorie needs", "Only one sign of tolerance, alongside abdominal examination"]'::jsonb, 3, 'Feeds are not stopped for moderate residuals without other signs.', 'Anaesthesia & Respiratory Care'),
(187, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Parenteral nutrition via a central line requires:', '["Hanging each bag for up to 72 hours", "No need for blood glucose monitoring", "Sharing the lumen with blood transfusions", "Strict asepsis, a dedicated lumen and glucose checks"]'::jsonb, 3, 'Line infection and hyperglycaemia are common complications.', 'Anaesthesia & Respiratory Care'),
(188, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Calorie needs of a critically ill adult in the early phase are about:', '["100 kcal/kg/day", "20–25 kcal/kg/day", "50 kcal/kg/day", "5 kcal/kg/day"]'::jsonb, 1, 'Overfeeding causes hyperglycaemia and increases CO₂ production.', 'Anaesthesia & Respiratory Care'),
(189, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Enteral feeding should be started in a critically ill patient:', '["Only after two weeks of IV fluids alone", "Only after the patient has been extubated", "Only when the patient asks for food", "Within 24–48 hours, once haemodynamically stable"]'::jsonb, 3, 'Early feeding maintains gut integrity.', 'Anaesthesia & Respiratory Care'),
(190, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Chest physiotherapy with percussion is contraindicated in:', '["Retained secretions in the lower lobes", "Cystic fibrosis with thick sputum", "Lobar atelectasis on the chest X-ray", "Unstable rib fractures and active bleeding"]'::jsonb, 3, 'It may worsen injury or bleeding.', 'Anaesthesia & Respiratory Care'),
(191, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Manual hyperinflation in ventilated patients aims to:', '["Replace the need for any suctioning", "Re-expand collapsed alveoli and move secretions", "Reduce oxygenation to rest the lungs", "Increase the depth of patient sedation"]'::jsonb, 1, 'It is avoided in patients with high PEEP needs or pneumothorax.', 'Anaesthesia & Respiratory Care'),
(192, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Early mobilisation in ICU is safe when:', '["The patient''s SpO₂ is below 85% on high FiO₂", "The patient''s intracranial pressure is uncontrolled", "The patient is on increasing doses of vasopressors", "The patient is cardiovascularly and respiratorily stable"]'::jsonb, 3, 'Protocols guide progression from sitting to walking.', 'Anaesthesia & Respiratory Care'),
(193, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'A sickle cell patient''s Hb electrophoresis showing HbF elevated after hydroxyurea means:', '["The patient has beta thalassaemia major as well", "The drug has failed and should be stopped now", "Hydroxyurea is raising fetal Hb, which reduces sickling", "The patient is dehydrated and needs IV fluids"]'::jsonb, 2, 'Hydroxyurea reduces crises and acute chest syndrome.', 'Anaesthesia & Respiratory Care'),
(194, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'A modified Allen''s test is performed before:', '["Central venous cannulation in the internal jugular", "Urinary catheterisation in men with retention", "Radial arterial puncture or arterial line insertion", "Lumbar puncture for CSF sampling in meningitis"]'::jsonb, 2, 'It checks ulnar collateral flow to the hand.', 'Anaesthesia & Respiratory Care'),
(195, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Culture and sensitivity results are used to:', '["Diagnose viral infections such as flu", "Start antibiotics only after seven days", "Avoid giving any antibiotics at all", "Narrow antibiotics to the most effective agent"]'::jsonb, 3, 'Antimicrobial stewardship reduces resistance.', 'Anaesthesia & Respiratory Care'),
(196, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Contact precautions for MRSA in ICU include:', '["Gloves, apron or gown, own equipment, hand hygiene", "Nursing in an open bay without isolation", "No special precautions for MRSA patients", "Airborne N95 masks only, without gloves"]'::jsonb, 0, 'Decolonisation may be used.', 'Anaesthesia & Respiratory Care'),
(197, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'The best teaching method for ICU nurses learning ventilator setup is:', '["Watching through the window from outside the room", "A lecture in a classroom with no practical session", "Demonstration with supervised practice and return demonstration", "Reading the ventilator manual alone at home"]'::jsonb, 2, 'Psychomotor skills need practice.', 'Anaesthesia & Respiratory Care'),
(198, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'A health talk to relatives of ICU patients should be:', '["Full of medical terms and abbreviations", "Simple, short and with time for questions", "Given without any preparation", "Very long, without any breaks"]'::jsonb, 1, 'Effective communication reduces anxiety.', 'Anaesthesia & Respiratory Care'),
(199, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Reflective practice after a difficult ICU case helps nurses to:', '["Avoid learning from the event", "Forget the event as fast as possible", "Learn from experience and improve care", "Find someone else to blame"]'::jsonb, 2, 'Models such as Gibbs'' cycle guide reflection.', 'Anaesthesia & Respiratory Care'),
(200, 'Anaesthesia, Nutrition, Physiotherapy, Laboratory and Teaching II', 'Critical thinking in ICU nursing involves:', '["Following every order exactly without any thought", "Relying only on memory for all clinical decisions", "Analysing data, questioning assumptions, reasoned decisions", "Avoiding decisions and waiting for others to act"]'::jsonb, 2, 'It improves patient safety.', 'Anaesthesia & Respiratory Care');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids,
